// Calibrated only for the bundled fixed aerial recording, not a universal classifier.
export function classifyParkingPixels(image,spaces,time){const {data,width,height}=image;return spaces.map((r,i)=>{const x0=Math.ceil((r[0]+r[2]*.1)*width),x1=Math.floor((r[0]+r[2]*.88)*width),y0=Math.ceil((r[1]+r[3]*.14)*height),y1=Math.floor((r[1]+r[3]*.86)*height);let dark=0,total=0;for(let y=y0;y<y1;y++)for(let x=x0;x<x1;x++){const k=(y*width+x)*4,v=.2126*data[k]+.7152*data[k+1]+.0722*data[k+2];dark+=v<105;total++;}const darkFraction=dark/Math.max(1,total);return{space:i+1,occupied:darkFraction>.15,darkFraction,time,method:'calibrated dark-pixel fraction >0.15, luminance <105; bundled video only'};});}
